-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
pending_records as (
    select
        resolution_record_key,
        deal_normalised_name,
        deal_strategy,
        deal_sourced_on,
        deal_originating_team
    from {{ ref("investment__deal_vault__resolution") }}
    where resolution_pending
),
candidate_pairs as (
    select
        left_side.resolution_record_key as record_key_a,
        right_side.resolution_record_key as record_key_b,
        {{ dpf_investment_entity_match_score("left_side.deal_normalised_name", "right_side.deal_normalised_name", "left_side.deal_strategy", "right_side.deal_strategy", "left_side.deal_sourced_on", "right_side.deal_sourced_on") }} as match_score
    from pending_records as left_side
    inner join pending_records as right_side
        on left_side.deal_originating_team = right_side.deal_originating_team
       and left_side.resolution_record_key < right_side.resolution_record_key
),
banded_pairs as (
    select
        record_key_a,
        record_key_b,
        match_score,
        case
            when match_score is null then 'unscored'
            when match_score >= 0.85 then 'accepted'
            when match_score >= 0.65 then 'review'
            else 'rejected'
        end as review_band
    from candidate_pairs
)

select
    record_key_a,
    record_key_b,
    match_score,
    review_band
from banded_pairs
